FILES={"src/lib/tour.ts": "", "src/lib/__tests__/tour.test.ts": "", "src/app/api/projects/[id]/tours/[tourId]/scenes/[sceneId]/hotspots/route.ts": "", "src/app/api/projects/[id]/tours/[tourId]/scenes/[sceneId]/hotspots/[hotspotId]/route.ts": ""}
EDITS=[["src/app/projects/[id]/tours/[tourId]/page.tsx", "import-tour", "ZnJvbSAnQC9saWIvdG91cic=", "aW1wb3J0IHsgdXBsb2FkRmlsZURpcmVjdCB9IGZyb20gJ0AvbGliL3VwbG9hZCc7", "aW1wb3J0IHsgdXBsb2FkRmlsZURpcmVjdCB9IGZyb20gJ0AvbGliL3VwbG9hZCc7CmltcG9ydCB7IGtpbmRUb1R5cGUsIGhvdHNwb3RMYWJlbCwgaXNEaXJlY3Rpb24gfSBmcm9tICdAL2xpYi90b3VyJzs="], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "iface-hotspot", "aW50ZXJmYWNlIEhvdHNwb3Qgew==", "aW50ZXJmYWNlIFNjZW5lIHsgaWQ6IHN0cmluZzsgbmFtZTogc3RyaW5nOyBpbWFnZVVybDogc3RyaW5nOyBpc0luaXRpYWw6IGJvb2xlYW47IHBvc2l0aW9uOiBudW1iZXI7IH0=", ""], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "iface-pannellum", "bW91c2VFdmVudFRvQ29vcmRz", "aW50ZXJmYWNlIFBhbm5lbGx1bVZpZXdlciB7CiAgZGVzdHJveTogKCkgPT4gdm9pZDsKICBsb2FkU2NlbmU6IChzY2VuZUlkOiBzdHJpbmcpID0+IHZvaWQ7CiAgb246IChldmVudDogc3RyaW5nLCBjYWxsYmFjazogKCkgPT4gdm9pZCkgPT4gdm9pZDsKfQ==", "aW50ZXJmYWNlIFBhbm5lbGx1bVZpZXdlciB7CiAgZGVzdHJveTogKCkgPT4gdm9pZDsKICBsb2FkU2NlbmU6IChzY2VuZUlkOiBzdHJpbmcpID0+IHZvaWQ7CiAgb246IChldmVudDogc3RyaW5nLCBjYWxsYmFjazogKCkgPT4gdm9pZCkgPT4gdm9pZDsKICBtb3VzZUV2ZW50VG9Db29yZHM6IChlOiBNb3VzZUV2ZW50KSA9PiBbbnVtYmVyLCBudW1iZXJdOwp9"], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "state-hotspots", "Y29uc3QgW2hvdHNwb3RzLCBzZXRIb3RzcG90c10=", "ICBjb25zdCBbcGFubmVsbHVtTG9hZGVkLCBzZXRQYW5uZWxsdW1Mb2FkZWRdID0gdXNlU3RhdGUoZmFsc2UpOw==", ""], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "viewer-hotspots", "aG90U3BvdHM6IGhzLA==", "", ""], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "hotspot-fns", "Y29uc3Qgc2F2ZUhvdHNwb3QgPSBhc3luYw==", "ICBjb25zdCBsb2FkU2NlbmVzID0gYXN5bmMgKCk6IFByb21pc2U8dm9pZD4gPT4gew==", ""], ["src/app/projects/[id]/tours/[tourId]/page.tsx", "render-hotspots", "77yLIEhvdHNwb3Q=", "ICAgICAgICAgICAgICA8ZGl2IHJlZj17dmlld2VyUmVmfSBjbGFzc05hbWU9ImZsZXgtMSIgc3R5bGU9e3sgbWluSGVpZ2h0OiAnNTAwcHgnLCBiYWNrZ3JvdW5kOiAnIzAwMCcgfX0gLz4=", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov - hotspots visites 360 ==")
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
    cache={}
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src and old not in src: print("  = deja",name); cache[p]=src; continue
        if old not in src: print("!! ANCRE KO:",name); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Module hotspots 360 applique. Aucun git push.")
if __name__=='__main__': main()
